import java.util.*;

public class Main {
    int calPoints(String[] ops) {
        List<Integer> scores = new ArrayList<>();                                   // a plain list, mutated the same way a stack would be
        for (String op : ops) {
            if (op.equals("C")) {
                scores.remove(scores.size() - 1);                                       // remove the invalid previous score entirely
            } else if (op.equals("D")) {
                scores.add(scores.get(scores.size() - 1) * 2);                             // double the previous score
            } else if (op.equals("+")) {
                scores.add(scores.get(scores.size() - 1) + scores.get(scores.size() - 2));    // sum of the previous TWO scores
            } else {
                scores.add(Integer.parseInt(op));                                             // a direct new score
            }
        }
        int total = 0;
        for (int s : scores) total += s;
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        String[] ops = {"5", "2", "C", "D", "+"};
        System.out.println(solution.calPoints(ops));
    }
}

