int calPoints(vector<string>& ops) {
    vector<int> scores;                                                                // a plain vector, mutated the same way a stack would be
    for (const string& op : ops) {
        if (op == "C") {
            scores.pop_back();                                                            // remove the invalid previous score entirely
        } else if (op == "D") {
            scores.push_back(scores.back() * 2);                                             // double the previous score
