            scores.push_back(scores[scores.size() - 1] + scores[scores.size() - 2]);          // sum of the previous TWO scores
        } else {
            scores.push_back(stoi(op));                                                       // a direct new score
        }
    }
    int total = 0;
    for (int s : scores) total += s;
    return total;
}

