import java.util.*;

public class Main {
    int calPoints(String[] ops) {
        Deque<Integer> stack = new ArrayDeque<>();                                       // the stack IS the running valid record
        for (String op : ops) {
            if (op.equals("C")) {
                stack.pop();
            } else if (op.equals("D")) {
                stack.push(stack.peek() * 2);
            } else if (op.equals("+")) {
                int top = stack.pop();
                int second = stack.peek();
                stack.push(top);
                stack.push(top + second);
            } else {
                stack.push(Integer.parseInt(op));
            }
        }
        int total = 0;
        for (int s : stack) total += s;                                                       // the final sum of everything still on the stack
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        String[] ops = {"5", "-2", "4", "C", "D", "9", "+", "+"};
        System.out.println(solution.calPoints(ops));
    }
}

